const items = $input.all();
const results = [];

for (let index = 0; index < items.length; index++) {
  const graph = items[index].json || {};
  const base = JSON.parse(JSON.stringify($item(index).$node["FB Action Switch"].json || {}));
  const isError = Boolean(graph.error || (typeof graph.statusCode === 'number' && graph.statusCode >= 400));

  let errorMessage = '';
  if (isError) {
    errorMessage = graph.error?.message || graph.message || graph.error_description || '';
    if (!errorMessage) {
      try {
        errorMessage = JSON.stringify(graph);
      } catch (error) {
        errorMessage = String(graph);
      }
    }
  }

  base.sheetStatus = isError ? 'FB_NEGATIVE_DELETE_ERROR' : 'FB_NEGATIVE_DELETED';
  base.actionResult = isError ? 'facebook_delete_error' : 'facebook_delete_success';
  base.actionError = isError ? errorMessage : '';

  base.facebook = base.facebook || {};
  base.facebook.graphResponse = graph;
  delete base.facebook.pageAccessToken;

  results.push({ json: base });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const data = JSON.parse(JSON.stringify(item.json || {}));
  const line = data.line || {};
  const targets = Array.isArray(line.targets) ? line.targets.filter(Boolean) : [];
  const token = (line.channelAccessToken || '').trim();
  const message = line.message;

  if (line.enabled && token && targets.length > 0 && message) {
    const endpoint = line.endpoint || (targets.length > 1
      ? 'https://api.line.me/v2/bot/message/multicast'
      : 'https://api.line.me/v2/bot/message/push');

    const payload = targets.length > 1
      ? { to: targets, messages: [{ type: 'text', text: message }], notificationDisabled: false }
      : { to: targets[0], messages: [{ type: 'text', text: message }], notificationDisabled: false };

    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: endpoint,
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: payload,
        json: true
      });
      data.actionResult = data.actionResult || 'line_notify_success';
      data.sheetNotifiedChannel = targets.length > 1 ? 'LINE(multicast)' : 'LINE(push)';
    } catch (error) {
      const errorData = error && error.response && error.response.data ? JSON.stringify(error.response.data) : (error.message || JSON.stringify(error));
      data.actionError = errorData;
      data.sheetStatus = `${data.sheetStatus || ''}|LINE_ERROR`;
    }
  }

  if (data.line) {
    delete data.line.channelAccessToken;
  }

  results.push({ json: data });
}

return results;
